//! Engine-v2 conformance: replays `packages/core/fixtures/engine/conformance.json` (generated by the
//! TypeScript engine) and requires identical outcomes — status, error, virtual duration, counters,
//! retry delays, timeouts, log lines, click/drag coordinates and typed text. Multi-monitor cases
//! also script displays and probe answers and compare final variables and every probe.
//! `dhash.json` checks the scene hash bit for bit.
#![allow(clippy::unwrap_used, clippy::expect_used)]

mod common;

use autoflow_engine::display::{dhash_bytes, hash_similarity, DisplayInfo};
use autoflow_engine::engine::{BackendError, ErrorCategory, InputAction, RunEvent, RunOptions};
use autoflow_engine::schema::{normalize_numbers, retry_delay_ms, Mulberry32, OnError, Target};
use autoflow_engine::{parse_flow, MockBackend, Platform};
use common::{fixtures_dir, run_with};
use serde_json::{json, Value as Json};
use std::collections::HashMap;
use std::sync::Arc;

fn cases() -> Vec<Json> {
    let path = fixtures_dir().join("engine/conformance.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str::<Json>(&text).expect("conformance.json is JSON").as_array().expect("array").clone()
}

fn point(t: &Target) -> Json {
    match t {
        Target::Point { x, y, .. } => json!([x, y]),
        Target::Region { x, y, w, h, .. } => json!([x, y, w, h]),
        other => panic!("unexpected target {other:?}"),
    }
}

fn script(v: &Json) -> HashMap<String, Vec<String>> {
    v.as_object()
        .map(|o| {
            o.iter().map(|(k, seq)| (k.clone(), seq.as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_owned()).collect())).collect()
        })
        .unwrap_or_default()
}

#[test]
fn engine_v2_matches_the_typescript_engine() {
    let all = cases();
    assert!(all.len() >= 10, "expected conformance cases, got {}", all.len());
    for c in all {
        let name = c["name"].as_str().unwrap().to_owned();
        let flow = parse_flow(&c["flow"]).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        let mut backend = MockBackend::new(Platform::Windows);
        if let Some(d) = c.get("displays") {
            let displays: Vec<DisplayInfo> = serde_json::from_value(d.clone()).expect("displays");
            backend = backend.with_displays(displays).with_pixels(script(&c["pixels"])).with_scene_hashes(script(&c["sceneHashes"]));
        }
        if let Some(ff) = c["failFirst"].as_object() {
            let kind = ff["type"].as_str().unwrap().to_owned();
            let mut left = ff["count"].as_u64().unwrap();
            backend = backend.with_hook(move |a: &InputAction| {
                if a.type_name() == kind && left > 0 {
                    left -= 1;
                    return Some(Err(BackendError::new(ErrorCategory::Target, "target not found")));
                }
                None
            });
        }
        let random = c["random"].as_f64().unwrap();
        let secrets = c["secrets"].as_object().cloned().unwrap_or_default();
        let opts = RunOptions {
            random: Some(Arc::new(move || random)),
            confirm_risk: Some(Box::new(|_| true)),
            secret: Some(Arc::new(move |n: &str| secrets.get(n).and_then(Json::as_str).map(str::to_owned))),
            ..RunOptions::default()
        };
        let ran = run_with(flow, backend, opts);
        let r = &ran.result;
        let e = &c["expect"];
        let got_status = serde_json::to_value(r.status).unwrap();
        assert_eq!(got_status, e["status"], "{name}: status");
        let got_error = r.error.as_ref().map_or(
            Json::Null,
            |err| json!({ "category": serde_json::to_value(err.category).unwrap(), "stepId": err.step_id, "message": err.message }),
        );
        assert_eq!(got_error, e["error"], "{name}: error");
        assert_eq!(json!(r.duration_ms), e["durationMs"], "{name}: durationMs");
        assert_eq!(json!(r.actions), e["actions"], "{name}: actions");
        assert_eq!(json!(r.iterations), e["iterations"], "{name}: iterations");
        assert_eq!(json!(r.steps), e["steps"], "{name}: steps");
        let delays: Vec<Json> = ran
            .events
            .iter()
            .filter_map(|ev| match ev {
                RunEvent::Retry { delay_ms, .. } => Some(json!(delay_ms)),
                _ => None,
            })
            .collect();
        assert_eq!(Json::Array(delays), e["retryDelays"], "{name}: retry delays");
        let timeouts: Vec<Json> = ran
            .events
            .iter()
            .filter_map(|ev| match ev {
                RunEvent::Timeout { step_id, .. } => Some(json!(step_id)),
                _ => None,
            })
            .collect();
        assert_eq!(Json::Array(timeouts), e["timeouts"], "{name}: timeouts");
        let logs: Vec<Json> = ran
            .events
            .iter()
            .filter_map(|ev| match ev {
                RunEvent::Log { message, .. } => Some(json!(message)),
                _ => None,
            })
            .collect();
        assert_eq!(Json::Array(logs), e["logs"], "{name}: logs");
        let state = ran.mock.lock();
        let targets: Vec<Json> = state
            .effects
            .iter()
            .flat_map(|fx| match &fx.action {
                InputAction::Click { target, .. } => vec![point(target)],
                InputAction::Drag { from, to, .. } => vec![point(from), point(to)],
                _ => vec![],
            })
            .collect();
        let (mut got, mut want) = (Json::Array(targets), e["targets"].clone());
        normalize_numbers(&mut got);
        normalize_numbers(&mut want);
        assert_eq!(got, want, "{name}: targets");
        assert_eq!(json!(state.typed), e["typed"], "{name}: typed");
        if let Some(want_probes) = e.get("probes") {
            let (mut got, mut want) = (json!(state.probes), want_probes.clone());
            normalize_numbers(&mut got);
            normalize_numbers(&mut want);
            assert_eq!(got, want, "{name}: probes");
        }
        if let Some(want_vars) = e.get("vars") {
            let mut got = serde_json::Map::new();
            for (k, v) in &r.vars {
                got.insert(k.clone(), v.to_json());
            }
            let (mut got, mut want) = (Json::Object(got), want_vars.clone());
            normalize_numbers(&mut got);
            normalize_numbers(&mut want);
            assert_eq!(got, want, "{name}: vars");
        }
    }
}

#[test]
fn dhash_matches_the_typescript_engine_bit_for_bit() {
    let path = fixtures_dir().join("engine/dhash.json");
    let fx: Json = serde_json::from_str(&std::fs::read_to_string(path).expect("dhash.json")).expect("JSON");
    let images = fx["images"].as_array().expect("images");
    assert!(images.len() >= 8);
    let mut hashes = HashMap::new();
    for im in images {
        let name = im["name"].as_str().unwrap();
        let hex = im["rgb"].as_str().unwrap();
        let bytes: Vec<u8> = (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect();
        let (w, h) = (usize::try_from(im["w"].as_u64().unwrap()).unwrap(), usize::try_from(im["h"].as_u64().unwrap()).unwrap());
        let got = dhash_bytes(&bytes, w, h, 3).expect("hash");
        assert_eq!(got, im["hash"].as_str().unwrap(), "{name}");
        hashes.insert(name.to_owned(), got);
    }
    for p in fx["pairs"].as_array().unwrap() {
        let (a, b) = (&hashes[p["a"].as_str().unwrap()], &hashes[p["b"].as_str().unwrap()]);
        assert!((hash_similarity(a, b) - p["similarity"].as_f64().unwrap()).abs() < f64::EPSILON, "{p}");
    }
}

#[test]
fn mulberry32_matches_the_reference_values() {
    let mut r = Mulberry32::new(42);
    #[allow(clippy::cast_possible_truncation)]
    let got: Vec<i64> = (0..3).map(|_| (r.next_f64() * 1e9).round() as i64).collect();
    assert_eq!(got, vec![601_103_752, 448_290_559, 852_465_793]);
}

#[test]
fn retry_delay_curves() {
    let p = |v: Json| serde_json::from_value::<OnError>(v).unwrap();
    let mut zero = || 0.0;
    let linear = p(json!({ "strategy": "retry", "retries": 3, "backoffMs": 500 }));
    assert_eq!((1..=3).map(|n| retry_delay_ms(&linear, n, &mut zero)).collect::<Vec<_>>(), vec![500, 1000, 1500]);
    let exp = p(json!({ "strategy": "retry", "backoffMs": 100, "backoff": "exponential", "maxBackoffMs": 1000 }));
    assert_eq!((1..=5).map(|n| retry_delay_ms(&exp, n, &mut zero)).collect::<Vec<_>>(), vec![100, 200, 400, 800, 1000]);
    let jit = p(json!({ "backoffMs": 400, "backoff": "fixed", "jitter": 0.5 }));
    assert_eq!(retry_delay_ms(&jit, 1, &mut || 0.5), 300);
    // Round-trips with the new optional fields and omits them when absent.
    assert_eq!(serde_json::to_value(&linear).unwrap(), json!({ "strategy": "retry", "retries": 3, "backoffMs": 500 }));
}

#[test]
fn structural_limits_and_bounds_are_enforced() {
    let mut nested = json!({ "id": "w", "type": "wait", "ms": 1 });
    for i in 0..40 {
        nested = json!({ "id": format!("g{i}"), "type": "group", "name": "g", "body": [nested] });
    }
    let doc = |steps: Json| json!({ "schemaVersion": "1.0", "id": "f", "name": "t", "steps": steps, "createdAt": "2026-10-19T00:00:00.000Z", "updatedAt": "2026-10-19T00:00:00.000Z" });
    let issues = parse_flow(&doc(json!([nested]))).expect_err("too deep");
    assert!(issues.iter().any(|i| i.message.contains("nested")), "{issues:?}");
    let far = json!([{ "id": "c", "type": "click", "target": { "kind": "point", "x": 1e300, "y": 0 } }]);
    assert!(parse_flow(&doc(far)).is_err());
    let bad_header = json!([{ "id": "h", "type": "http", "url": "https://x.dev", "headers": { "bad header": "v" } }]);
    assert!(parse_flow(&doc(bad_header)).is_err());
    let ok = json!([{ "id": "w", "type": "wait", "ms": 10, "stepTimeoutMs": 5, "onError": { "strategy": "retry", "backoff": "exponential", "jitter": 0.3 } }]);
    let flow = parse_flow(&doc(ok)).expect("valid");
    assert_eq!(flow.steps[0].step_timeout_ms, Some(5));
}
